const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  AlignmentType, LevelFormat, BorderStyle, WidthType, ShadingType,
  VerticalAlign, HeadingLevel
} = require('docx');
const fs = require('fs');

const MAROON = "6B1E2E";
const CREAM = "FAF7F4";
const BLACK = "1A1A1A";
const DARK_GREEN = "2C4A3E";
const LIGHT_MAROON = "F2E8EA";
const WHITE = "FFFFFF";

const noBorder = { style: BorderStyle.NONE, size: 0, color: "FFFFFF" };
const noBorders = { top: noBorder, bottom: noBorder, left: noBorder, right: noBorder };

function spacer(pts = 40) {
  return new Paragraph({ children: [new TextRun("")], spacing: { before: 0, after: pts } });
}

function sectionHeader(text) {
  return new Paragraph({
    children: [new TextRun({ text, font: "Garamond", size: 18, bold: true, color: WHITE, allCaps: true })],
    spacing: { before: 80, after: 80 },
    shading: { fill: MAROON, type: ShadingType.CLEAR },
    indent: { left: 180, right: 180 }
  });
}

function serviceRow(title, bullets) {
  const content = [
    new Paragraph({
      children: [new TextRun({ text: title, font: "Garamond", size: 19, bold: true, color: MAROON })],
      spacing: { before: 60, after: 30 }
    }),
    ...bullets.map(b =>
      new Paragraph({
        children: [new TextRun({ text: b, font: "Garamond", size: 17, color: BLACK })],
        numbering: { reference: "bullets", level: 0 },
        spacing: { before: 0, after: 20 }
      })
    )
  ];
  return content;
}

// Two-column service layout using a table
function twoColServices(leftItems, rightItems) {
  const buildCell = (items) => new TableCell({
    borders: noBorders,
    width: { size: 4500, type: WidthType.DXA },
    margins: { top: 0, bottom: 0, left: 100, right: 100 },
    children: items.flat()
  });

  return new Table({
    width: { size: 9200, type: WidthType.DXA },
    columnWidths: [4500, 4700],
    rows: [
      new TableRow({
        children: [buildCell(leftItems), buildCell(rightItems)]
      })
    ]
  });
}

const doc = new Document({
  numbering: {
    config: [
      {
        reference: "bullets",
        levels: [{
          level: 0, format: LevelFormat.BULLET, text: "\u2022",
          alignment: AlignmentType.LEFT,
          style: { paragraph: { indent: { left: 360, hanging: 200 } } }
        }]
      }
    ]
  },
  sections: [{
    properties: {
      page: {
        size: { width: 12240, height: 15840 },
        margin: { top: 720, right: 720, bottom: 720, left: 720 }
      }
    },
    children: [

      // HEADER BLOCK
      new Paragraph({
        children: [new TextRun({ text: "THE LUXORA COLLECTIVE", font: "Garamond", size: 36, bold: true, color: WHITE, allCaps: true, characterSpacing: 80 })],
        alignment: AlignmentType.CENTER,
        spacing: { before: 100, after: 30 },
        shading: { fill: MAROON, type: ShadingType.CLEAR },
        indent: { left: 0, right: 0 }
      }),
      new Paragraph({
        children: [new TextRun({ text: "Revenue Growth Partners for Independent Med Spa Owners", font: "Garamond", size: 20, color: WHITE, italics: true })],
        alignment: AlignmentType.CENTER,
        spacing: { before: 0, after: 100 },
        shading: { fill: MAROON, type: ShadingType.CLEAR }
      }),

      spacer(40),

      // POSITIONING STATEMENT
      new Paragraph({
        children: [new TextRun({ text: "Most med spas are generating attention, but losing revenue in the process.", font: "Garamond", size: 20, bold: true, color: MAROON, italics: true })],
        alignment: AlignmentType.CENTER,
        spacing: { before: 0, after: 30 }
      }),
      new Paragraph({
        children: [new TextRun({ text: "Luxora is a premium, done-with-you growth partner for independent med spas generating $500K to $2M annually. We increase revenue from the inside out, starting with a Revenue Leak Audit and Market Blueprint before recommending any new investment.", font: "Garamond", size: 18, color: BLACK })],
        alignment: AlignmentType.CENTER,
        spacing: { before: 0, after: 50 }
      }),

      // SECTION: WHAT WE DO
      sectionHeader("What We Do"),
      spacer(30),

      twoColServices(
        [
          serviceRow("1. Revenue Leak Audit", [
            "Identify where revenue is lost before adding any spend",
            "Front desk gaps, unconverted consults, no-show patterns",
            "Stagnant clients, missing memberships, weak package architecture",
            "Outcome: Immediate clarity on what is costing you money today"
          ]),
          spacer(20),
          serviceRow("2. Market Blueprint", [
            "Competitive positioning in your specific market",
            "Offer and pricing strategy aligned to your ideal client",
            "Revenue and capacity planning with clear milestones",
            "Outcome: A data-backed direction for growth"
          ]),
          spacer(20),
          serviceRow("3. Conversion System Buildout", [
            "CRM setup, pipeline tracking, and lead follow-up flows",
            "SMS, email, and call sequences for booked, attending clients",
            "Deposit and no-show reduction strategies",
            "Front desk scripting and booking frameworks",
            "Outcome: More leads becoming appointments that show"
          ]),
          spacer(20),
          serviceRow("4. Consult and Sales Optimization", [
            "Consult structure, flow, and offer presentation",
            "Package and membership close frameworks",
            "Pricing psychology and conversion rate improvement",
            "Outcome: Higher revenue per consult"
          ]),
        ],
        [
          serviceRow("5. Membership and LTV Systems", [
