            "Package structuring, bundling, upsells, and cross-sells",
            "Retention and rebooking flows that run without the owner",
            "Outcome: Clients stay longer and spend more"
          ]),
          spacer(20),
          serviceRow("6. Staff Sales Training", [
            "Role-specific training for front desk and providers",
            "Scripting for bookings, upsells, and membership conversations",
            "Knowledge transfer so the team can execute independently",
            "Outcome: Revenue-generating team, not order takers"
          ]),
          spacer(20),
          serviceRow("7. Marketing and Lead Acquisition", [
            "Paid ad strategy on Meta and Google once systems are solid",
            "Offer-based campaigns with lead capture and automation",
            "Reputation engine and partnership-driven referral systems",
            "Outcome: Qualified lead flow that actually converts"
          ]),
          spacer(20),
          serviceRow("8. CRM, AI Follow-Up, and Ongoing Strategy", [
            "Automated workflows and AI-assisted follow-up sequences",
            "Show rate, close rate, and LTV monitoring",
            "Bi-weekly strategy calls, performance reviews, and adjustments",
            "Outcome: Predictable growth you understand and control"
          ]),
        ]
      ),

      spacer(40),

      // GUARANTEE + WHO THIS IS FOR — side by side
      new Table({
        width: { size: 9200, type: WidthType.DXA },
        columnWidths: [4500, 4700],
        rows: [
          new TableRow({
            children: [
              new TableCell({
                borders: noBorders,
                shading: { fill: LIGHT_MAROON, type: ShadingType.CLEAR },
                margins: { top: 120, bottom: 120, left: 180, right: 180 },
                width: { size: 4500, type: WidthType.DXA },
                children: [
                  new Paragraph({
                    children: [new TextRun({ text: "Our Guarantee", font: "Garamond", size: 20, bold: true, color: MAROON, allCaps: true })],
                    spacing: { before: 0, after: 60 }
                  }),
                  new Paragraph({
                    children: [new TextRun({ text: "We guarantee a minimum 2X return on your investment in the form of new or recovered revenue. If that target is not met, we continue working with you until it is.", font: "Garamond", size: 18, color: BLACK })],
                    spacing: { before: 0, after: 0 }
                  }),
                ]
              }),
              new TableCell({
                borders: noBorders,
                shading: { fill: CREAM, type: ShadingType.CLEAR },
                margins: { top: 120, bottom: 120, left: 180, right: 180 },
                width: { size: 4700, type: WidthType.DXA },
                children: [
                  new Paragraph({
                    children: [new TextRun({ text: "Who This Is For", font: "Garamond", size: 20, bold: true, color: MAROON, allCaps: true })],
                    spacing: { before: 0, after: 60 }
                  }),
                  ...[
                    "Independent med spas generating $500K to $2M annually",
                    "Owners who know something is off in their growth",
                    "Teams ready to implement, improve, and operate with confidence",
                    "Owners who want capability and control, not dependency on an agency"
                  ].map(item => new Paragraph({
                    children: [new TextRun({ text: item, font: "Garamond", size: 18, color: BLACK })],
                    numbering: { reference: "bullets", level: 0 },
                    spacing: { before: 0, after: 20 }
                  }))
                ]
              })
            ]
          })
        ]
      }),

      spacer(40),

      // CTA
      new Paragraph({
        children: [new TextRun({ text: "Ready to find your Revenue Leaks?", font: "Garamond", size: 22, bold: true, color: WHITE })],
        alignment: AlignmentType.CENTER,
        shading: { fill: DARK_GREEN, type: ShadingType.CLEAR },
        spacing: { before: 100, after: 40 },
        indent: { left: 0, right: 0 }
      }),
      new Paragraph({
        children: [new TextRun({ text: "Book your Revenue Leak Audit at theluxoracollective.co", font: "Garamond", size: 19, color: WHITE, italics: true })],
        alignment: AlignmentType.CENTER,
        shading: { fill: DARK_GREEN, type: ShadingType.CLEAR },
        spacing: { before: 0, after: 100 }
      }),
    ]
  }]
});

Packer.toBuffer(doc).then(buffer => {
  fs.writeFileSync("/mnt/user-data/outputs/Luxora_Collective_One_Pager.docx", buffer);
  console.log("Done.");
});

