const noBorders = { top: noBorder, bottom: noBorder, left: noBorder, right: noBorder };

// Page is 12240 wide, margins are 720 each side = 10800 content
// To bleed header to page edges, add margins back: 10800 + 720 + 720 = 12240
// Then use negative indent to push past margins
const CONTENT_WIDTH = 10800;
const PAGE_WIDTH = 12240;
const MARGIN = 720;

const COL_L = 5300;
const COL_R = 5500;

function spacer(pts) {
  return new Paragraph({ children: [new TextRun("")], spacing: { before: 0, after: pts } });
}

function serviceTitle(text) {
  return new Paragraph({
    children: [new TextRun({ text, font: "Garamond", size: 18, bold: true, color: MAROON })],
