  });
}

function bullet(text) {
  return new Paragraph({
    children: [new TextRun({ text, font: "Garamond", size: 16, color: BLACK })],
    numbering: { reference: "bullets", level: 0 },
    spacing: { before: 0, after: 14 }
  });
}

// Full-bleed table: width = full page, negative indent to escape margins
function fullBleedTable(children) {
  return new Table({
    width: { size: PAGE_WIDTH, type: WidthType.DXA },
    columnWidths: [PAGE_WIDTH],
    indent: { size: -MARGIN, type: WidthType.DXA },
    rows: [new TableRow({
      children: [new TableCell({
        borders: noBorders,
        width: { size: PAGE_WIDTH, type: WidthType.DXA },
        shading: { fill: MAROON, type: ShadingType.CLEAR },
        margins: { top: 0, bottom: 0, left: MARGIN, right: MARGIN },
